<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import AppIcon from '../../components/AppIcon.vue'
import { apiBase, setApiBase, request, upload, imageUrl, type Crop, type Meta, type CaseRecord, type KnowledgeCard, type Source } from '../../lib/api'
import { crops, stages, regions, dateLabel, statusLabel } from '../../lib/options'

type Tab = 'identify' | 'history' | 'knowledge'
const tab = ref<Tab>('identify')
const crop = ref<Crop>('wheat')
const stage = ref('不清楚')
const note = ref('')
const photo = ref('')
const meta = ref<Meta | null>(null)
const online = ref(false)
const refreshing = ref(true)
const busy = ref(false)
const busyText = ref('')
const error = ref('')
const records = ref<CaseRecord[]>([])
const cards = ref<KnowledgeCard[]>([])
const current = ref<CaseRecord | null>(null)
const resultTab = ref<'advice' | 'chat'>('advice')
const chatText = ref('')
const sending = ref(false)
const query = ref('')
const filter = ref('all')
const selectedCard = ref<KnowledgeCard | null>(null)
const settingsOpen = ref(false)
const regionOpen = ref(false)
const apiDraft = ref(apiBase())
const province = ref('河南省')
const city = ref('南阳市')
const district = ref('暂不填写区县')
const customLocation = ref('')
const useCustom = ref(false)
const provinces = Object.keys(regions)
const cities = computed(() => Object.keys(regions[province.value] || {}))
const districts = computed(() => regions[province.value]?.[city.value] || ['暂不填写区县'])
const location = computed(() => useCustom.value ? customLocation.value || '地区待补充' : [province.value, city.value, district.value === '暂不填写区县' ? '' : district.value].filter(Boolean).join(' / '))
const activeCrop = computed(() => crops.find(c => c.id === crop.value)!)
const modelReady = computed(() => meta.value?.models.find(m => m.crop === crop.value)?.ready || false)
const realRecords = computed(() => records.value.filter(r => !r.is_demo).length)
const filteredRecords = computed(() => records.value.filter(r => (filter.value === 'all' || r.crop === filter.value) && (r.title + r.note + r.crop_name).includes(query.value)))
const filteredCards = computed(() => cards.value.filter(c => (filter.value === 'all' || c.crop === filter.value || c.crop === 'general') && (c.title + c.summary + c.keywords.join('')).includes(query.value)))
const navTitle = computed(() => current.value ? '问诊详情' : ({ identify: '拍照识别', history: '问诊记录', knowledge: '植保知识' })[tab.value])
const lastImage = computed(() => current.value ? imageUrl(current.value) : '')
const qualityIssues = computed(() => { const images = current.value?.images || []; return images[images.length - 1]?.quality.issues || [] })
const draftExtra = ref(false)
const editOpen = ref(false)
const editStage = ref('不清楚')
const editNote = ref('')
const editLocation = ref('')

function showError(e: unknown) { error.value = e instanceof Error ? e.message : '操作未完成，请重试' }
async function refresh() {
  error.value = ''
  refreshing.value = true
  try {
    const [system, history, knowledge] = await Promise.all([request<Meta>('/api/meta'), request<{ items: CaseRecord[] }>('/api/cases'), request<{ items: KnowledgeCard[] }>('/api/knowledge')])
    meta.value = system; records.value = history.items; cards.value = knowledge.items; online.value = true
  } catch (e) { online.value = false; showError(e) } finally { refreshing.value = false }
}
onMounted(refresh)
onLoad(options => { if (options?.case) openCase(String(options.case)) })
function navigate(next: Tab) { tab.value = next; current.value = null; query.value = ''; filter.value = 'all'; error.value = '' }
function chooseCrop(value: Crop) { crop.value = value; stage.value = '不清楚' }
function setProvince(event: { detail: { value: string | number } }) { province.value = provinces[Number(event.detail.value)]; city.value = cities.value[0]; district.value = '暂不填写区县' }
function setCity(event: { detail: { value: string | number } }) { city.value = cities.value[Number(event.detail.value)]; district.value = '暂不填写区县' }
function setDistrict(event: { detail: { value: string | number } }) { district.value = districts.value[Number(event.detail.value)] }
function setStage(event: { detail: { value: string | number } }) { stage.value = stages[crop.value][Number(event.detail.value)] }

function choosePhoto(source: 'album' | 'camera' = 'album', supplement = false) {
  uni.chooseImage({ count: 1, sizeType: ['compressed'], sourceType: [source], success: async result => {
    const filePath = result.tempFilePaths[0]
    const files = result.tempFiles as { size: number }[]
    if (files?.[0]?.size > 8 * 1024 * 1024) { error.value = '图片不能超过 8MB，请压缩后重试'; return }
    if (supplement) await addPhoto(filePath)
    else { photo.value = filePath; error.value = '' }
  }, fail: fail => { if (!fail.errMsg?.includes('cancel')) error.value = '未能打开相册或相机，请检查权限后重试' } })
}
function handleDrop(event: unknown) {
  // #ifdef H5
  const file = (event as DragEvent).dataTransfer?.files[0]
  if (!file) return
  if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) { error.value = '请选择 JPG、PNG 或 WebP 图片'; return }
  if (file.size > 8 * 1024 * 1024) { error.value = '图片不能超过 8MB'; return }
  photo.value = URL.createObjectURL(file)
  // #endif
}
async function startCase() {
  if (!photo.value || busy.value) return
  busy.value = true; busyText.value = '正在上传图片并处理问诊…'; error.value = ''
  try { current.value = await upload('/api/cases', photo.value, { crop: crop.value, location: location.value, stage: stage.value, note: note.value }); resultTab.value = 'advice'; await refresh() } catch (e) { showError(e) } finally { busy.value = false }
}
async function demo(value = crop.value) {
  if (busy.value) return
  busy.value = true; busyText.value = '正在打开演示样例…'; error.value = ''
  try { current.value = await request<CaseRecord>('/api/cases/demo', 'POST', { crop: value }); resultTab.value = 'advice'; await refresh() } catch (e) { showError(e) } finally { busy.value = false }
}
async function openCase(id: string) {
  busy.value = true; busyText.value = '正在打开问诊记录…'; error.value = ''
  try { current.value = await request<CaseRecord>('/api/cases/' + id); resultTab.value = 'advice' } catch (e) { showError(e) } finally { busy.value = false }
}
async function addPhoto(path: string) {
  if (!current.value || busy.value) return
  busy.value = true; busyText.value = '正在保存补充照片…'; error.value = ''
  try { current.value = await upload('/api/cases/' + current.value.id + '/images', path, {}); await refresh() } catch (e) { showError(e) } finally { busy.value = false }
}
async function sendMessage(text = chatText.value) {
  if (!current.value || sending.value || !text.trim()) return
  const value = text.trim(); const id = current.value.id
  sending.value = true; chatText.value = ''; error.value = ''
  try { await request('/api/cases/' + id + '/messages', 'POST', { text: value }); const updated = await request<CaseRecord>('/api/cases/' + id); if (current.value?.id === id) current.value = updated; await refresh() } catch (e) { if (current.value?.id === id) chatText.value = value; showError(e) } finally { sending.value = false }
}
function editCase() { if (!current.value) return; editStage.value = current.value.stage; editNote.value = current.value.note; editLocation.value = current.value.location; editOpen.value = true }
async function saveCase() {
  if (!current.value) return
  busy.value = true; error.value = ''
  try { current.value = await request<CaseRecord>('/api/cases/' + current.value.id + '/context', 'POST', { stage: editStage.value, location: editLocation.value, note: editNote.value }); editOpen.value = false; await refresh() } catch (e) { showError(e) } finally { busy.value = false }
}
function removeCase(record: CaseRecord) {
  uni.showModal({ title: '删除这条问诊？', content: '这条记录、关联照片与聊天会一起删除。', confirmText: '删除记录', confirmColor: '#aa443c', success: async result => {
    if (!result.confirm) return
    try { await request('/api/cases/' + record.id, 'DELETE'); if (current.value?.id === record.id) current.value = null; await refresh() } catch (e) { showError(e) }
  } })
}
function openSource(source: Source) {
  // #ifdef H5
  window.open(source.url, '_blank', 'noopener,noreferrer')
  return
  // #endif
  // #ifndef H5
  uni.setClipboardData({ data: source.url })
  // #endif
}
async function saveServer() { try { setApiBase(apiDraft.value.trim()); await refresh(); if (online.value) settingsOpen.value = false } catch (e) { showError(e) } }
function openChat() { resultTab.value = 'chat'; uni.pageScrollTo({ scrollTop: 0, duration: 0 }) }
function viewPhoto() { if (current.value) uni.previewImage({ urls: [lastImage.value] }) }
function viewImage(id: string) { if (current.value) uni.previewImage({ urls: current.value.images.map(i => imageUrl(current.value!, i.id)), current: imageUrl(current.value, id) }) }
</script>

<template>
  <view class="app-shell">
    <view class="sidebar">
      <view class="brand" @click="navigate('identify')"><view class="brand-mark"><AppIcon name="leaf" :size="28" white /></view><view><text class="brand-name">AgriVision</text><text class="brand-caption">宛农植保助手</text></view></view>
      <text class="nav-caption">田间工作台</text>
      <button class="nav-item" :class="{ active: tab === 'identify' && !current }" @click="navigate('identify')"><AppIcon name="camera" /><text>识别问诊</text><text class="nav-arrow">↗</text></button>
      <button class="nav-item" :class="{ active: tab === 'history' }" @click="navigate('history')"><AppIcon name="history" /><text>问诊记录</text><text class="nav-count">{{ records.length }}</text></button>
      <button class="nav-item" :class="{ active: tab === 'knowledge' }" @click="navigate('knowledge')"><AppIcon name="book" /><text>植保知识</text></button>
      <view class="sidebar-note"><view class="small-leaf"><AppIcon name="wheat" :size="24" /></view><text class="note-heading">立足南阳，服务中原</text><text class="muted small">从清晰的照片开始，
把每一次田间观察记录下来。</text></view>
      <view class="sidebar-bottom"><button class="system-link" @click="settingsOpen = true"><AppIcon name="settings" :size="18" /><text>运行与连接</text></button><text class="version">开发测试版 1.0</text></view>
    </view>

    <view class="main-shell">
      <view class="topbar"><view class="breadcrumb"><text class="desktop-only">工作台</text><text class="crumb-slash desktop-only">/</text><text>{{ navTitle }}</text></view><view class="top-actions"><view class="online-state" :class="{ disconnected: !online }"><view class="status-dot" /><text>{{ refreshing ? '正在连接本地服务' : online ? '本地服务已连接' : '服务未连接' }}</text></view><button class="location-button" @click="regionOpen = true"><AppIcon name="location" :size="17" /><text>{{ city.replace('市','') }} · {{ province.replace('省','') }}</text><AppIcon name="chevron" :size="13" /></button><button class="mobile-settings" aria-label="运行与连接" @click="settingsOpen = true"><AppIcon name="settings" /></button></view></view>

      <view v-if="error" class="error-banner" role="alert"><AppIcon name="info" :size="20" /><text class="flex-one">{{ error }}</text><button v-if="!online" class="text-link" @click="refresh">重新连接</button><button class="icon-button" @click="error = ''"><AppIcon name="close" :size="16" /></button></view>
      <view v-if="busy" class="loading-line"><view class="spinner" /><text>{{ busyText || '正在保存…' }}</text></view>

      <view class="content" v-if="!current && tab === 'identify'">
        <view class="hero"><view class="hero-copy"><view class="hero-eyebrow"><view class="eyebrow-dot" /><text>田间发现，及时了解</text></view><text class="hero-title">作物有异常？<text class="hero-title-break">拍照问一问。</text></text><text class="hero-description">小麦 · 玉米 · 花生<text class="hero-divider">/</text>图片记录、植保资料与持续咨询</text></view><image src="/static/field-art.png" mode="aspectFit" class="hero-art" /><text class="hero-coordinate desktop-only">NANYANG · CENTRAL PLAINS</text></view>

        <view class="home-grid"><view class="panel identify-panel"><view class="section-heading"><view><text class="section-title">新建一次问诊</text><text class="section-description">选好作物，上传一张清晰的症状照片</text></view><button class="text-link demo-link" :disabled="busy || !online" @click="demo()">体验演示 <text>↗</text></button></view>
          <view class="crop-grid"><button v-for="option in crops" :key="option.id" class="crop-option" :class="{ selected: crop === option.id }" @click="chooseCrop(option.id)"><image :src="'/static/crops/' + option.id + '.png'" class="crop-art" mode="aspectFit" /><view class="crop-copy"><text class="crop-name">{{ option.name }}</text><text class="crop-status">{{ meta?.models.find(m => m.crop === option.id)?.ready ? '图片识别已就绪' : '资料咨询可用' }}</text></view><view class="radio-indicator"><view v-if="crop === option.id" /></view></button></view>

          <view id="upload-zone" class="upload-zone" :class="{ 'has-photo': !!photo }" @dragover.prevent @drop.prevent="handleDrop">
            <template v-if="!photo"><view class="upload-icon"><AppIcon name="camera" :size="38" /></view><text class="upload-title">让症状拍得更清楚一点</text><text class="upload-description">靠近病叶、对好焦，再补一张整株照片</text><view class="upload-buttons"><button class="primary-button" @click="choosePhoto('album')"><AppIcon name="upload" :size="18" white /><text>选择症状照片</text></button><!-- #ifndef H5 --><button class="secondary-button" @click="choosePhoto('camera')"><AppIcon name="camera" :size="18" /><text>拍照</text></button><!-- #endif --></view><text class="upload-footnote">JPG / PNG / WebP · 单张不超过 8MB<text class="desktop-only"> · 支持拖入图片</text></text></template>
            <template v-else><image :src="photo" class="selected-photo" mode="aspectFit" /><view class="photo-actions"><text class="badge">照片已选择</text><button class="secondary-button compact" @click="choosePhoto('album')">更换照片</button><button class="icon-button" @click="photo = ''"><AppIcon name="close" :size="18" /></button></view></template>
          </view>
          <view class="form-meta"><button class="meta-field" @click="regionOpen = true"><view class="field-label"><AppIcon name="location" :size="16" /><text>种植地区</text></view><view class="field-value"><text>{{ location }}</text><AppIcon name="chevron" :size="13" /></view></button><picker class="meta-field" :range="stages[crop]" :value="stages[crop].indexOf(stage)" @change="setStage"><view class="field-label"><AppIcon name="leaf" :size="16" /><text>当前生育期</text></view><view class="field-value"><text>{{ stage === '不清楚' ? '选择生育期（可选）' : stage }}</text><AppIcon name="chevron" :size="13" /></view></picker></view>
          <button class="optional-toggle" @click="draftExtra = !draftExtra"><AppIcon :name="draftExtra ? 'close' : 'plus'" :size="15" /><text>{{ draftExtra ? '收起补充信息' : '再描述一下症状（可选）' }}</text></button><textarea v-if="draftExtra" v-model="note" class="note-input" placeholder="例如：这两天发现叶片异常，田边零星几株，最近还没用药……" :maxlength="2000" />
          <view class="submit-row"><text class="muted small model-note"><view class="mini-dot" />{{ modelReady ? '识别后可继续补图与咨询' : '模型准备中，可先保存图片并咨询' }}</text><button class="primary-button submit-button" :disabled="!photo || busy || !online" @click="startCase"><text>{{ modelReady ? '开始识别' : '保存图片并咨询' }}</text><text>→</text></button></view>
        </view>

        <view class="right-column"><view class="panel guide-panel"><view class="section-heading"><text class="section-title small-title">一张好照片，从这里开始</text><AppIcon name="image" :size="20" /></view><view class="guide-line" v-for="(item, index) in ['拍清症状，避免过远和反光', '叶片正面、背面都值得看看', '整株和田间分布也能提供线索']" :key="item"><text class="step-number">0{{ index + 1 }}</text><text>{{ item }}</text></view><button class="quiet-link" @click="selectedCard = cards.find(c => c.id === 'photo_guide') || null">查看拍摄指南 <text>↗</text></button></view>
        <view class="panel recent-panel"><view class="section-heading"><text class="section-title small-title">最近问诊</text><button class="text-link small" @click="navigate('history')">全部 →</button></view><template v-if="records.length"><button v-for="record in records.slice(0,3)" :key="record.id" class="recent-item" @click="openCase(record.id)"><view class="record-crop-icon"><AppIcon :name="record.crop" :size="25" /></view><view class="flex-one"><text class="recent-title">{{ record.title }}</text><text class="muted small">{{ dateLabel(record.created_at) }} · {{ record.crop_name }}</text></view><AppIcon name="arrow" :size="16" /></button></template><view v-else class="empty-recent"><AppIcon name="history" :size="30" /><text>{{ refreshing ? '正在读取问诊记录…' : '还没有问诊记录' }}</text><text class="muted small">照片、建议和对话会一起保存在这里</text></view></view>
        <view class="local-note"><view class="local-note-heading"><AppIcon name="leaf" :size="19" /><text>先观察，再做决定</text></view><text>结合照片、种植情况和专业资料，让每一步处理更有依据。</text></view></view></view>
        <view class="page-footer"><text>AgriVision · 让田间观察有迹可循</text><text>开发测试版 1.0</text></view>
      </view>

      <view v-if="current" class="content case-content" :class="{ 'chat-content': resultTab === 'chat' }"><view class="page-heading"><view><button class="back-link" @click="current = null"><text>←</text><text>返回{{ tab === 'history' ? '记录' : '工作台' }}</text></button><text class="page-title">这一次，继续了解作物</text><text class="muted">{{ current.crop_name }} · {{ current.location }} · {{ dateLabel(current.created_at) }}</text></view><button class="secondary-button compact" @click="editCase"><AppIcon name="settings" :size="16" /><text>补充情况</text></button></view>
        <view v-if="current.is_demo" class="demo-banner"><AppIcon name="info" :size="18" /><text>演示样例用于体验完整流程，图示与结果不代表对真实照片的识别。</text></view>
        <view class="case-grid" :class="{ 'chat-mode': resultTab === 'chat' }"><view class="case-left"><view class="panel case-photo-panel"><view class="section-heading"><text class="section-title small-title">{{ current.is_demo ? '作物示意' : '症状照片' }}</text><text class="badge neutral">{{ current.is_demo ? '演示' : current.images.length + ' 张照片' }}</text></view><view class="case-photo-wrap" :class="{ illustrated: current.is_demo }" @click="viewPhoto"><image :src="lastImage" class="case-photo" mode="aspectFit" /><view v-if="!current.is_demo" class="zoom-hint"><AppIcon name="zoom" :size="16" /><text>查看原图</text></view></view><view v-if="!current.is_demo" class="image-strip"><image v-for="image in current.images" :key="image.id" :src="imageUrl(current,image.id)" mode="aspectFill" @click="viewImage(image.id)" /></view><button v-if="!current.is_demo" class="secondary-button full-width" :disabled="busy || current.images.length >= 6" @click="choosePhoto('album', true)"><AppIcon name="plus" :size="18" /><text>补充一张照片</text></button></view>
          <view class="panel case-information"><text class="section-title small-title">问诊信息</text><view class="detail-row"><text>作物</text><text>{{ current.crop_name }}</text></view><view class="detail-row"><text>生育期</text><text>{{ current.stage }}</text></view><view class="detail-row"><text>地区</text><text>{{ current.location }}</text></view><text v-if="current.note" class="case-note">{{ current.note }}</text><view v-if="current.versions.length > 1" class="version-note">已保存 {{ current.versions.length }} 次识别记录，补图会更新本次建议。</view><button class="quiet-link" @click="removeCase(current)"><AppIcon name="trash" :size="15" /><text>删除这条记录</text></button></view></view>
          <view class="case-right"><view class="result-tabs"><button :class="{ active: resultTab === 'advice' }" @click="resultTab = 'advice'">结果与建议</button><button :class="{ active: resultTab === 'chat' }" @click="openChat">继续咨询 <text class="tab-message-count" v-if="current.messages.length">{{ current.messages.length / 2 }}</text></button></view>
          <view v-if="resultTab === 'advice'" class="panel result-panel"><view class="result-status"><view class="result-status-icon"><AppIcon :name="current.status === 'identified' ? 'check' : 'leaf'" :size="23" /></view><text class="badge" :class="{ amber: current.status !== 'identified' && !current.is_demo }">{{ statusLabel(current.status) }}</text></view><text class="result-title">{{ current.title }}</text><text class="result-description">{{ current.advice.summary }}</text><view v-if="qualityIssues.length" class="quality-box"><text v-for="issue in qualityIssues" :key="issue">{{ issue }}</text></view>
            <view class="result-divider" /><text class="section-title small-title">接下来可以这样做</text><view class="action-line" v-for="(action,index) in current.advice.actions" :key="action"><text class="action-index">{{ index + 1 }}</text><text>{{ action }}</text></view>
            <view class="product-section"><view class="section-heading"><text class="section-title small-title">适用产品与用药依据</text><AppIcon name="book" :size="19" /></view><view v-if="current.advice.products.length"><view v-for="product in current.advice.products" :key="product.id" class="product-card"><text class="strong">{{ product.name }}</text><text>{{ product.ingredient }} · {{ product.formulation }}</text><text>{{ product.instructions }}</text><button class="text-link" @click="openSource({ title: product.name, url: product.label_url, date: '' })">查看产品标签 ↗</button></view></view><text v-else class="muted">暂未匹配到资料完整的适用产品。可补充具体药品标签，由农技人员核对作物、对象和用法。</text></view>
            <view v-if="current.advice.sources.length" class="source-section"><text class="field-label">参考资料</text><button v-for="source in current.advice.sources" :key="source.url" class="source-link" @click="openSource(source)"><AppIcon name="book" :size="15" /><text>{{ source.title }}</text><text>↗</text></button></view>
            <view v-if="current.candidates.length" class="candidate-section"><text class="field-label">模型候选 · 分数用于比较，不是确诊概率</text><view class="candidate-row" v-for="candidate in current.candidates" :key="candidate.id"><text>{{ candidate.name }}</text><text>{{ (candidate.score * 100).toFixed(1) }}%</text></view></view>
            <button class="primary-button full-width consult-button" @click="openChat"><AppIcon name="chat" :size="20" white /><text>补充情况，继续咨询</text><text>→</text></button>
          </view>
          <view v-else class="panel chat-panel"><view class="chat-summary"><AppIcon :name="current.crop" :size="22" /><view><text class="strong">{{ current.crop_name }} · {{ statusLabel(current.status) }}</text><text class="muted small">本次咨询关联当前照片与问诊记录</text></view><view class="chat-provider"><view class="mini-dot" /><text>{{ meta?.deepseek_configured ? '智能咨询' : '本地资料解读' }}</text></view></view>
            <scroll-view scroll-y class="messages" :scroll-into-view="'message-' + current.messages.length" :scroll-with-animation="true"><view v-if="!current.messages.length" class="chat-welcome"><view class="welcome-mark"><AppIcon name="leaf" :size="30" /></view><text class="welcome-title">继续说说田里的情况</text><text class="muted">可以描述症状出现的时间、分布和近期用药。我们一起把需要核对的信息补齐。</text></view><view v-for="(message,index) in current.messages" :key="index" :id="'message-' + (index + 1)" class="message-row" :class="message.role"><view v-if="message.role === 'assistant'" class="assistant-avatar"><AppIcon name="leaf" :size="18" /></view><view class="message-content"><text v-if="message.role === 'assistant'" class="message-author">宛农助手 <text>{{ message.provider === 'deepseek' ? '智能咨询' : message.provider === 'rules' ? '用药资料核对' : '资料解读' }}</text></text><text class="message-bubble">{{ message.text }}</text><text v-if="message.notice" class="small muted">{{ message.notice }}</text><button v-for="source in message.sources" :key="source.url" class="message-source" @click="openSource(source)">↗ {{ source.title }}</button><view v-for="product in message.products" :key="product.id" class="product-card"><text class="strong">{{ product.name }}</text><text>{{ product.instructions }}</text></view></view></view><view v-if="sending" class="typing-state"><view class="spinner" /><text>正在整理相关资料与回答…</text></view></scroll-view>
            <view class="chat-compose"><view class="quick-questions"><button v-for="question in ['还需要补充什么信息？', '如何拍清楚症状？', '用药前需要核对什么？']" :key="question" :disabled="sending" @click="sendMessage(question)">{{ question }}</button></view><view class="composer-input"><textarea v-model="chatText" placeholder="描述症状，或继续问一问……" :maxlength="2000" :auto-height="true" :disabled="sending" /><button class="send-button" aria-label="发送咨询消息" :disabled="!chatText.trim() || sending" @click="sendMessage()"><AppIcon name="arrow" :size="23" white /></button></view><text class="composer-footnote">具体用药结合产品标签及农技复核</text></view>
          </view></view></view>
      </view>

      <view v-if="!current && tab === 'history'" class="content"><view class="page-heading"><view><text class="eyebrow">FIELD NOTES</text><text class="page-title">把田间变化，记录下来</text><text class="muted">共 {{ records.length }} 条问诊 · {{ realRecords }} 条图片问诊</text></view><button class="primary-button" @click="navigate('identify')"><AppIcon name="plus" :size="18" white /><text>新建问诊</text></button></view><view class="panel list-panel"><view class="list-toolbar"><view class="filter-tabs"><button :class="{ active: filter === 'all' }" @click="filter = 'all'">全部</button><button v-for="option in crops" :key="option.id" :class="{ active: filter === option.id }" @click="filter = option.id">{{ option.name }}</button></view><view class="search-field"><AppIcon name="search" :size="18" /><input v-model="query" placeholder="搜索作物、症状或备注" /></view></view><view v-if="!filteredRecords.length" class="large-empty"><image src="/static/crops/wheat.png" mode="aspectFit" /><text class="section-title">{{ records.length ? '没有找到匹配记录' : '从第一次田间观察开始' }}</text><text class="muted">{{ records.length ? '试试其他关键词或作物筛选' : '上传照片，或先体验一条演示样例' }}</text><button v-if="!records.length" class="secondary-button" :disabled="!online" @click="demo()">体验演示样例 →</button></view><view v-for="record in filteredRecords" :key="record.id" class="history-row"><button class="history-main" @click="openCase(record.id)"><image :src="record.images.length ? imageUrl(record) : '/static/crops/' + record.crop + '.png'" class="history-image" mode="aspectFill" /><view class="flex-one"><view class="history-title-line"><text class="history-title">{{ record.title }}</text><text class="badge neutral">{{ statusLabel(record.status) }}</text></view><text class="muted small">{{ record.crop_name }} · {{ record.location }} · {{ dateLabel(record.updated_at) }}</text></view><AppIcon name="arrow" :size="20" /></button><button class="icon-button history-delete" aria-label="删除问诊记录" @click="removeCase(record)"><AppIcon name="trash" :size="18" /></button></view></view></view>

      <view v-if="!current && tab === 'knowledge'" class="content"><view class="page-heading"><view><text class="eyebrow">GROW WITH KNOWLEDGE</text><text class="page-title">有依据，才更有把握</text><text class="muted">小麦、玉米、花生的植保资料与拍摄指南</text></view><text class="knowledge-count">{{ cards.length }} 份资料</text></view><view class="knowledge-toolbar"><view class="filter-tabs"><button :class="{ active: filter === 'all' }" @click="filter = 'all'">全部作物</button><button v-for="option in crops" :key="option.id" :class="{ active: filter === option.id }" @click="filter = option.id">{{ option.name }}</button></view><view class="search-field"><AppIcon name="search" :size="18" /><input v-model="query" placeholder="搜索病害、症状或拍摄问题" /></view></view><view class="knowledge-grid"><button v-for="card in filteredCards" :key="card.id" class="panel knowledge-card" @click="selectedCard = card"><view class="knowledge-card-top"><view class="knowledge-icon"><AppIcon :name="card.crop === 'general' ? 'camera' : card.crop" :size="27" /></view><text class="badge neutral">{{ card.category }}</text></view><text class="knowledge-title">{{ card.title }}</text><text class="knowledge-summary">{{ card.summary }}</text><view class="knowledge-card-bottom"><text>{{ card.sources.length ? '附资料来源' : '拍摄与操作建议' }}</text><AppIcon name="arrow" :size="18" /></view></button></view><view v-if="!filteredCards.length" class="large-empty"><AppIcon name="search" :size="35" /><text class="section-title">没有找到对应资料</text><text class="muted">试试病害名称或其他症状关键词</text></view></view>
