    <view v-if="selectedCard" class="modal-backdrop" @click.self="selectedCard = null"><view class="modal knowledge-modal"><view class="modal-header"><view><text class="eyebrow">{{ selectedCard.category }}</text><text class="modal-title">{{ selectedCard.title }}</text></view><button class="icon-button" aria-label="关闭资料" @click="selectedCard = null"><AppIcon name="close" /></button></view><scroll-view scroll-y class="modal-scroll"><text class="article-summary">{{ selectedCard.summary }}</text><text class="section-title small-title">建议检查与补充</text><view class="action-line" v-for="(action,index) in selectedCard.actions" :key="action"><text class="action-index">{{ index + 1 }}</text><text>{{ action }}</text></view><view v-if="selectedCard.sources.length" class="source-section"><text class="section-title small-title">资料来源</text><button v-for="source in selectedCard.sources" :key="source.url" class="source-link" @click="openSource(source)"><AppIcon name="book" :size="17" /><view class="flex-one"><text>{{ source.title }}</text><text class="muted small">{{ source.date }}</text></view><text>↗</text></button></view></scroll-view><button class="primary-button full-width" @click="selectedCard = null; navigate('identify')">带着照片，开始一次问诊 →</button></view></view>

